const lockBridgeEvent = `-- name: LockBridgeEvent :exec
SELECT pg_advisory_xact_lock($1::int, hashtext(format('%s/%s', $2::bigint, $3::text)))
`

type LockBridgeEventParams struct {
	LockClass    int32
	ConnectionID int64
	EventID      string
}

// LockBridgeEvent takes, until the transaction ends, the claim lock of one event of a Bridge Connection (the class
// bridgeEventLockClass of internal/connections, 0x6d75_0007, keyed by hashtext of the Connection's id and the event
// id), so that a second copy of the event — a push retried while the first runs, or an overlapping poll — waits for
// the first and then finds its id recorded. It never locks a row; a collision of the hash only serializes two events.
func (q *Queries) LockBridgeEvent(ctx context.Context, arg LockBridgeEventParams) error {
	_, err := q.db.Exec(ctx, lockBridgeEvent, arg.LockClass, arg.ConnectionID, arg.EventID)
	return err
}

const lockConnection = `-- name: LockConnection :one
SELECT id, public_id, type, version
FROM connections
WHERE org_id = $1 AND public_id = $2 AND deleted_at IS NULL
FOR NO KEY UPDATE
`

type LockConnectionParams struct {
	OrgID    int64
	PublicID string
}

type LockConnectionRow struct {
	ID       int64
	PublicID string
	Type     string
	Version  int64
}

// LockConnection locks a Connection that is not deleted for a change or its deletion.
func (q *Queries) LockConnection(ctx context.Context, arg LockConnectionParams) (LockConnectionRow, error) {
	row := q.db.QueryRow(ctx, lockConnection, arg.OrgID, arg.PublicID)
	var i LockConnectionRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.Type,
		&i.Version,
	)
	return i, err
}

const lockDemo = `-- name: LockDemo :exec
SELECT pg_advisory_xact_lock($1::bigint)
`

// LockDemo serializes the demo start-up step of replicas that start together, until the transaction ends.
func (q *Queries) LockDemo(ctx context.Context, key int64) error {
	_, err := q.db.Exec(ctx, lockDemo, key)
	return err
}

const lockUpdates = `-- name: LockUpdates :exec
SELECT pg_advisory_xact_lock($1::int, hashint8($2::bigint))
`

type LockUpdatesParams struct {
	LockClass int32
	ID        int64
}

// LockUpdates takes, until the transaction ends, the update lock of a Telegram Connection (class
// db.TelegramUpdateLockClass, keyed by hashint8 of its id), so that a second poller or a webhook request with the same
// update waits for the first and then skips it; the delivery worker tries it shared, without waiting, before an edit of
// a Root message of the Connection (delivery's TryShareUpdateLock). It never locks the connections row, which a save
// of the Connection holds while setWebhook runs; a collision of the hash only serializes the updates of two
// Connections.
func (q *Queries) LockUpdates(ctx context.Context, arg LockUpdatesParams) error {
	_, err := q.db.Exec(ctx, lockUpdates, arg.LockClass, arg.ID)
	return err
}

const markConnectionDeleted = `-- name: MarkConnectionDeleted :exec
UPDATE connections
SET deleted_at = $1::timestamptz, updated_at = $1::timestamptz, version = version + 1,
    bot_token_ciphertext = NULL, bot_token_key_id = NULL, proxy_password_ciphertext = NULL,
    proxy_password_key_id = NULL, telegram_webhook_secret_ciphertext = NULL, telegram_webhook_secret_key_id = NULL,
    bridge_push_secret_ciphertext = NULL, bridge_push_secret_key_id = NULL, slack_app_token_ciphertext = NULL,
    slack_app_token_key_id = NULL, slack_signing_secret_ciphertext = NULL, slack_signing_secret_key_id = NULL
WHERE org_id = $2 AND id = $3
`

type MarkConnectionDeletedParams struct {
	Now   time.Time
	OrgID int64
	ID    int64
}

// MarkConnectionDeleted soft-deletes a Connection and wipes its secrets: it leaves every list and reads as missing,
// the row stays for the history of its Destinations.
func (q *Queries) MarkConnectionDeleted(ctx context.Context, arg MarkConnectionDeletedParams) error {
	_, err := q.db.Exec(ctx, markConnectionDeleted, arg.Now, arg.OrgID, arg.ID)
	return err
}

const pruneBridgeEventsSeen = `-- name: PruneBridgeEventsSeen :execrows
DELETE FROM bridge_events_seen e
WHERE e.org_id = $1
  AND (e.connection_id, e.event_id) IN (
      SELECT s.connection_id, s.event_id
      FROM bridge_events_seen s
      WHERE s.org_id = $1 AND s.seen_at < $2::timestamptz
      ORDER BY s.seen_at
      LIMIT $3
      FOR UPDATE SKIP LOCKED)
`

type PruneBridgeEventsSeenParams struct {
	OrgID     int64
	Before    time.Time
	BatchSize int32
}

// PruneBridgeEventsSeen deletes at most @batch_size records of Bridge event ids seen before @before, skipping rows
// another transaction holds.
func (q *Queries) PruneBridgeEventsSeen(ctx context.Context, arg PruneBridgeEventsSeenParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneBridgeEventsSeen, arg.OrgID, arg.Before, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const recordBridgeEvent = `-- name: RecordBridgeEvent :exec
INSERT INTO bridge_events_seen (org_id, connection_id, event_id, seen_at)
VALUES ($1, $2, $3, $4::timestamptz)
ON CONFLICT (org_id, connection_id, event_id) DO NOTHING
`

