const storeBridgeEventsCursor = `-- name: StoreBridgeEventsCursor :execrows
UPDATE connections
SET bridge_events_cursor = $1::text
WHERE org_id = $2 AND id = $3 AND type = 'bridge' AND version = $4 AND deleted_at IS NULL
`

type StoreBridgeEventsCursorParams struct {
	Cursor  pgtype.Text
	OrgID   int64
	ID      int64
	Version int64
}

// StoreBridgeEventsCursor stores where the poller of a Bridge Connection goes on — null drops the cursor — unless the
// Connection changed since the poller read it: a poller of an earlier version, or of a frozen old Leader, writes
// nothing. It is not a change of the configuration.
func (q *Queries) StoreBridgeEventsCursor(ctx context.Context, arg StoreBridgeEventsCursorParams) (int64, error) {
	result, err := q.db.Exec(ctx, storeBridgeEventsCursor,
		arg.Cursor,
		arg.OrgID,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const storeUpdateOffset = `-- name: StoreUpdateOffset :exec
UPDATE connections
SET telegram_update_offset = GREATEST(coalesce(telegram_update_offset, $1::bigint), $1::bigint)
WHERE org_id = $2 AND id = $3 AND type = 'telegram' AND bot_token_updated_at = $4::timestamptz
`

type StoreUpdateOffsetParams struct {
	Next           int64
	OrgID          int64
	ID             int64
	TokenUpdatedAt time.Time
}

// StoreUpdateOffset raises telegram_update_offset of a Telegram Connection to @next; it never lowers it, so that a
// poller of a frozen old Leader cannot move it back. It changes nothing when the bot token was set again since
// @token_updated_at, which forgot telegram_update_offset: the ids of another bot's updates start elsewhere. It is not
// a change of the configuration.
func (q *Queries) StoreUpdateOffset(ctx context.Context, arg StoreUpdateOffsetParams) error {
	_, err := q.db.Exec(ctx, storeUpdateOffset,
		arg.Next,
		arg.OrgID,
		arg.ID,
		arg.TokenUpdatedAt,
	)
	return err
}

